provider "aws" {
  region = "us-west-2"
}

# IAM Role for Elastic Beanstalk EC2 instances
resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkWebTier",
    "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkWorkerTier",
    "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
  ]
}

# IAM Instance Profile for Elastic Beanstalk EC2 instances
resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "my_api_app" {
  name        = "my_api_app"
  description = "My API Application"
}

# VPC
resource "aws_vpc" "my_vpc" {
  cidr_block = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "my-vpc"
  }
}

# Subnet
resource "aws_subnet" "my_subnet" {
  vpc_id            = aws_vpc.my_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"

  tags = {
    Name = "my-subnet"
  }
}

# Launch Configuration
resource "aws_launch_configuration" "my_launch_config" {
  image_id              = "ami-0c55b159cbfafe1f0" # Example AMI ID, replace with a valid one
  instance_type         = "t3.micro"
  iam_instance_profile  = aws_iam_instance_profile.eb_ec2_profile.name
  security_groups       = ["default"] # Replace with actual security group IDs
  key_name              = "my-key-pair" # Replace with actual key pair name
}

# Autoscaling Group
resource "aws_autoscaling_group" "my_asg" {
  name                 = "my-asg"
  launch_configuration = aws_launch_configuration.my_launch_config.name
  min_size             = 1
  max_size             = 3
  vpc_zone_identifier  = [aws_subnet.my_subnet.id]

  tag {
    key                 = "Name"
    value               = "my-asg"
    propagate_at_launch = true
  }

  # Setting up autoscaling based on CPU utilization
  initial_lifecycle_hook {
    name                 = "before-init"
    lifecycle_transition = "autoscaling:EC2_INSTANCE_LAUNCHING"
    default_result       = "CONTINUE"
    heartbeat_timeout    = 300
  }

  # Setting up autoscaling policies
  scaling_policy {
    name                   = "cpu-auto-scaling"
    adjustment_type        = "ChangeInCapacity"
    cooldown               = 300
    scaling_adjustment     = 2
    policy_type            = "TargetTrackingScaling"
    target_tracking_configuration {
      predefined_metric_specification {
        predefined_metric_type = "ASGAverageCPUUtilization"
      }
      target_value = 50.0
    }
  }
}

# Elastic Beanstalk Environment
resource "aws_elastic_beanstalk_environment" "my_env" {
  name                = "my-env"
  application         = aws_elastic_beanstalk_application.my_api_app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.3.1 running Python 3.8"

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "3"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = "t3.micro"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }
}
```

