```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Elastic Beanstalk EC2 instances
resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# Instance Profile for Elastic Beanstalk EC2 instances
resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# S3 Bucket to store the application version
resource "aws_s3_bucket" "sampleapril26426" {
  bucket = "sampleapril26426"
}

# S3 Object containing the application version
resource "aws_s3_object" "examplebucket_object" {
  bucket = aws_s3_bucket.sampleapril26426.bucket
  key    = "examplebucket_object"
  source = "path/to/your/application.zip"
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "myapp" {
  name = "myapp"
}

# Elastic Beanstalk Application Version
resource "aws_elastic_beanstalk_application_version" "version" {
  name        = "version"
  application = aws_elastic_beanstalk_application.myapp.name
  bucket      = aws_s3_bucket.sampleapril26426.bucket
  key         = aws_s3_object.examplebucket_object.key
}

# Elastic Beanstalk Environment
resource "aws_elastic_beanstalk_environment" "myenv" {
  name                = "myenv"
  application         = aws_elastic_beanstalk_application.myapp.name
  version_label       = aws_elastic_beanstalk_application_version.version.name
  solution_stack_name = "64bit Amazon Linux 2 v3.3.1 running Python 3.8"
}
```

This Terraform configuration sets up the necessary AWS resources to deploy an Elastic Beanstalk environment with an application version. It includes an IAM role and instance profile for the EC2 instances, an S3 bucket and object to store the application version, an Elastic Beanstalk application, an application version, and finally, the environment itself.

