provider "aws" {
  region = "us-west-2"
}

# IAM Role for Elastic Beanstalk EC2 instances
resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "eb_ec2_policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "elasticbeanstalk:*",
            "ec2:*",
            "cloudformation:*",
            "autoscaling:*",
            "logs:*",
            "rds:*"
          ]
          Effect = "Allow"
          Resource = "*"
        }
      ]
    })
  }
}

# Attach EC2 policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_ec2_policy_to_role" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2FullAccess"
  role       = aws_iam_role.eb_ec2_role.name
}

# IAM Instance Profile for Elastic Beanstalk EC2 instances
resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# RDS Parameter Group
resource "aws_db_parameter_group" "my_db1_param_group" {
  name   = "my-db1-param-group"  # Changed to lowercase alphanumeric characters
  family = "mysql5.6"

  parameter {
    name  = "character_set_server"
    value = "utf8"
  }

  parameter {
    name  = "character_set_client"
    value = "utf8"
  }
}

# RDS Database Instance
resource "aws_db_instance" "my_db1" {
  instance_class = "db.t3.micro"
  allocated_storage = 20
  engine         = "mysql"
  engine_version = "5.6"
  username       = "admin"
  password       = "securepassword"
  parameter_group_name = aws_db_parameter_group.my_db1_param_group.name
}

# Auto Scaling Group
resource "aws_autoscaling_group" "eb_autoscaling_group" {
  name                 = "eb-autoscaling-group"
  launch_configuration = "your-launch-configuration-name"  # Replace with actual launch configuration name
  min_size             = 1
  max_size             = 3
  desired_capacity     = 2
  vpc_zone_identifier  = ["subnet-12345678", "subnet-87654321"]  # Replace with actual subnet IDs

  tag {
    key                 = "Name"
    value               = "eb-autoscaling-group"
    propagate_at_launch = true
  }

  # Scaling policy based on CPU utilization
  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_iam_instance_profile.eb_ec2_profile
  ]
}
