Here is the corrected Terraform configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

provider "random" {}

# IAM Role for Elastic Beanstalk AppVersion Lifecycle
resource "aws_iam_role" "beanstalk_service_role" {
  name = "elastic-beanstalk-appversion-lifecycle-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      },
    ]
  })
}

# S3 Bucket to store the application version source bundle
resource "aws_s3_bucket" "elastic_beanstalk_bucket" {
  bucket = "elastic-beanstalk-app-version-bucket-${random_string.suffix.result}"
  acl    = "private"
}

# Random string suffix for the S3 bucket name
resource "random_string" "suffix" {
  length  = 8
  special = false
}

# S3 Object containing the application version source bundle
resource "aws_s3_object" "elastic_beanstalk_app_version" {
  bucket = aws_s3_bucket.elastic_beanstalk_bucket.id
  key    = "application-version.zip"
  source = "path/to/application-version.zip"
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "elastic_beanstalk_app" {
  name        = "my-elastic-beanstalk-app"
  description = "Elastic Beanstalk Application with AppVersion Lifecycle"

  appversion_lifecycle {
    service_role          = aws_iam_role.beanstalk_service_role.arn
    max_count             = 10
    max_age_in_days       = 365
    delete_source_from_s3 = true
