### Terraform HCL Program

This Terraform configuration creates a basic AWS CodeBuild project with an example IAM role and a GitHub source. The IAM role is configured with the necessary permissions for CodeBuild operations.

```hcl
provider "aws" {
  region = "us-east-1"
}

# Create an IAM role for CodeBuild
resource "aws_iam_role" "codebuild_iam_role" {
  name = "codebuild-iam-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      },
    ]
  })

  inline_policy {
    name = "codebuild-policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect = "Allow"
          Action = [
            "logs:CreateLogGroup",
            "logs:CreateLogStream",
            "logs:PutLogEvents",
            "s3:*",
            "ec2:CreateNetworkInterface",
            "ec2:DescribeDhcpOptions",
            "ec2:DescribeNetworkInterfaces",
            "ec2:DeleteNetworkInterface",
            "ec2:DescribeSubnets",
            "ec2:DescribeSecurityGroups",
            "ec2:DescribeVpcs",
            "codeconnections:GetConnectionToken",
            "codeconnections:GetConnection"
          ]
          Resource = "*"
        },
      ]
    })
  }
}

# Create a CodeBuild project
resource "aws_codebuild_project" "basic_codebuild_project" {
  name         = "basic-codebuild-project"
  description  = "Basic CodeBuild project with GitHub source"
  service_role = aws_iam_role.codebuild_iam_role.arn

  artifacts {
    type = "NO_ARTIFACTS"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux2-x86_64-standard:4.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }

  source {
    type            = "GITHUB"
    location        = "https://github.com/example/example.git"
    git_clone_depth = 1
  }

  tags = {
    Environment = "Test"
  }
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **IAM Role**: An IAM role named `codebuild-iam-role` is created with an assume role policy that allows CodeBuild to assume the role. An inline policy is attached to grant necessary permissions for logging, S3 access, EC2 network interface operations, and CodeBuild connections.
3. **CodeBuild Project**: A CodeBuild project named `basic-codebuild-project` is created. It uses the IAM role created earlier. The project has no artifacts, a Linux container environment, and a GitHub source.

