### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# Create an IAM role for CodeBuild
resource "aws_iam_role" "example_iam_role" {
  name = "example-codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      },
    ]
  })
}

# Attach policies to the IAM role
resource "aws_iam_role_policy" "example_iam_policy" {
  role   = aws_iam_role.example_iam_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DescribeDhcpOptions",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeVpcs",
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = "ec2:CreateNetworkInterfacePermission"
        Resource = "arn:aws:ec2:us-east-1:123456789012:network-interface/*"
        Condition = {
          StringEquals = {
            "ec2:Subnet" = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]
          }
          StringEquals = {
            "ec2:AuthorizedService" = "codebuild.amazonaws.com"
          }
        }
      },
      {
        Effect = "Allow"
        Action = "s3:*"
        Resource = [
          "arn:aws:s3:::example-bucket",
          "arn:aws:s3:::example-bucket/*",
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "codeconnections:GetConnectionToken",
          "codeconnections:GetConnection"
        ]
        Resource = "arn:aws:codestar-connections:us-east-1:123456789012:connection/guid-string"
      }
    ]
  })
}

# Create a CodeBuild project
resource "aws_codebuild_project" "example_codebuild_project" {
  name         = "example-codebuild-project"
  description  = "Example CodeBuild project"
  service_role = aws_iam_role.example_iam_role.arn

