### Description

This Terraform configuration creates an AWS CodeBuild project with the following components:

1. **IAM Role**: An IAM role specifically for CodeBuild with the necessary permissions.
2. **Environment Variables**: Environment variables to be used during the build process.
3. **Secondary Sources**: Additional sources for the build project.
4. **Secondary Artifacts**: Additional artifacts produced by the build.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for CodeBuild
data "aws_iam_policy_document" "codebuild_assume_role_policy" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "codebuild_role" {
  name               = "codebuild-role"
  assume_role_policy = data.aws_iam_policy_document.codebuild_assume_role_policy.json
}

data "aws_iam_policy_document" "codebuild_permissions" {
  statement {
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "s3:*",
      "ec2:CreateNetworkInterface",
      "ec2:DescribeDhcpOptions",
      "ec2:DescribeNetworkInterfaces",
      "ec2:DeleteNetworkInterface",
      "ec2:DescribeSubnets",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeVpcs",
      "ec2:CreateNetworkInterfacePermission",
      "codeconnections:GetConnectionToken",
      "codeconnections:GetConnection"
    ]

    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "codebuild_policy" {
  role   = aws_iam_role.codebuild_role.name
  policy = data.aws_iam_policy_document.codebuild_permissions.json
}

# CodeBuild Project
resource "aws_codebuild_project" "example_codebuild_project" {
  name          = "example-codebuild-project"
  description   = "Example CodeBuild Project"
  service_role  = aws_iam_role.codebuild_role.arn
  build_timeout = 60

  artifacts {
    type = "NO_ARTIFACTS"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux2-x86_64-standard:4.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"

    environment_variable {
      name  = "ENV_VAR_1"
      value = "value1"
    }

    environment_variable {
      name  = "ENV_VAR_2"
      value = "value2"
    }
  }

  source {
    type            = "GITHUB"
    location        = "https://github.com/example/repo.git"
    git_clone_depth = 1
  }

  secondary_sources {
    source_identifier = "secondary-source"
    type              = "GITHUB"
    location          = "https://github.com/example/secondary-repo.git"
    git_clone_depth   = 1
  }

  secondary_source_version {
    source_identifier = "secondary-source"
    source_version    = "main"
  }

  secondary_artifacts {
    artifact_identifier = "secondary-artifact"
    type                = "S3"
    location            = "my-bucket/secondary-artifacts"
  }

  tags = {
    Environment = "Development"
  }
}
```

### Explanation

- **IAM Role**: The `aws_iam_role` resource creates an IAM role with an assume role policy that allows CodeBuild to assume the role. The `aws_iam_role_policy` resource attaches a policy to the role that grants necessary permissions for CodeBuild operations.

- **CodeBuild Project**: The `aws_codebuild_project` resource defines the CodeBuild project with the specified name, description, and service role. It includes environment variables, a primary source, secondary sources, secondary source versions, and secondary artifacts.

- **Artifacts and Sources**: The `artifacts` block specifies that no artifacts are produced. The `source` block defines the primary source, and the `secondary_sources` and `secondary_artifacts` blocks define additional sources and artifacts.

This configuration ensures that the CodeBuild project is properly set up with the necessary IAM role and configurations.

