### Description
The Terraform program defines an AWS Lex bot for ordering pizza with a follow-up question. It includes the necessary IAM roles and policies, a Lambda function to handle the pizza order logic, an AWS Lex intent to capture pizza details, and an AWS Lex bot to manage the conversation flow. The configuration ensures that all resources are properly linked and that the Lambda function has the required permissions.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_execution_role.name
}

resource "aws_lambda_function" "pizza_order_lambda" {
  function_name = "pizza_order_lambda"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "lambda_function_payload.zip"

  source_code_hash = filebase64sha256("lambda_function_payload.zip")
}

resource "aws_lex_intent" "order_pizza_intent" {
  name           = "OrderPizzaIntent"
  description    = "Intent to order pizza"
  sample_utterances = [
    "I want a {PizzaSize} pizza",
    "Order {Quantity} {PizzaSize} pizzas"
  ]

  fulfillment_activity {
    type = "CodeHook"
    code_hook {
      message_version = "1"
      uri             = aws_lambda_function.pizza_order_lambda.invoke_arn
    }
  }

  slot {
    name            = "PizzaSize"
    slot_constraint = "Required"
    slot_type       = "AMAZON.LITERAL"
    sample_utterances = [
      "small",
      "medium",
      "large"
    ]
  }

  slot {
    name            = "Quantity"
    slot_constraint = "Required"
    slot_type       = "AMAZON.NUMBER"
  }

  follow_up_prompt {
    prompt {
      max_attempts = 2
    }
    rejection_statement {
      message {
        content      = "No problem, let's move on."
        content_type = "PlainText"
      }
    }
  }
}

resource "aws_lex_bot" "order_pizza_bot" {
  name             = "OrderPizzaBot"
  child_directed     = false
  locale           = "en-US"
  process_behavior = "BUILD"
  voice_id         = "Joanna"

  abort_statement {
    message {
      content      = "Sorry, I am not able to assist at this time."
      content_type = "PlainText"
    }
  }

  clarification_prompt {
    max_attempts = 2
    message {
      content      = "I didn't understand you, what would you like to do?"
      content_type = "PlainText"
    }
  }

  intent {
    intent_name    = aws_lex_intent.order_pizza_intent.name
    intent_version = "$LATEST"
  }
}
```

This configuration ensures that the AWS Lex bot is correctly set up with the necessary components, including the Lambda function for handling the pizza order logic. The IAM roles and policies ensure that the Lambda function has the required permissions to execute.

