### Description
This Terraform configuration creates an AWS Lex bot named `OrderPizzaBot` that handles pizza orders. It includes an intent named `OrderPizzaIntent` which defines the slots for pizza size, quantity, and crust type. The bot uses this intent to interact with users and fulfill their pizza orders. The configuration also includes a conclusion statement that is displayed after the intent is successfully fulfilled.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_lex_intent" "order_pizza_intent" {
  name           = "OrderPizzaIntent"
  description    = "Intent to order a pizza"
  sample_utterances = [
    "I want a pizza",
    "Can I order a pizza?",
    "I'd like to order a {PizzaSize} pizza",
    "Order {Quantity} {PizzaSize} pizzas with {CrustType} crust"
  ]

  fulfillment_activity {
    type = "ReturnIntent"
  }

  slot {
    name            = "PizzaSize"
    slot_constraint = "Required"
    slot_type       = "AMAZON.NUMBER"
    sample_utterances = [
      "large",
      "medium",
      "small"
    ]
  }

  slot {
    name            = "Quantity"
    slot_constraint = "Required"
    slot_type       = "AMAZON.NUMBER"
    sample_utterances = [
      "one",
      "two",
      "three"
    ]
  }

  slot {
    name            = "CrustType"
    slot_constraint = "Required"
    slot_type       = "AMAZON.NUMBER"
    sample_utterances = [
      "thin",
      "thick",
      "stuffed"
    ]
  }

  conclusion_statement {
    message {
      content      = "Your pizza order has been placed. Thank you!"
      content_type = "PlainText"
    }
  }
}

