### Description
This Terraform configuration creates an AWS Lex bot named "OrderPizzaBot" for ordering pizzas. It also creates an intent named "OrderPizzaIntent" that the bot will use. The `nlu_intent_confidence_threshold` is set to 0.5 for the bot.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_lex_intent" "order_pizza_intent" {
  name = "OrderPizzaIntent"

  sample_utterances = [
    "I want to order a pizza",
    "Can I order a pizza?",
    "I'd like to get a pizza",
    "Order me a pizza",
    "I need a pizza"
  ]

  fulfillment_activity {
    type = "ReturnIntent"
  }

  confirmation_prompt {
    max_attempts = 2

    message {
      content      = "Sure, I can help you order a pizza. What size would you like?"
      content_type = "PlainText"
    }
  }

  rejection_statement {
    message {
      content      = "Okay, I will not place your pizza order."
      content_type = "PlainText"
    }
  }

  slot {
    name            = "PizzaSize"
    slot_constraint = "Required"
    slot_type       = "AMAZON.LITERAL"

    sample_utterances = [
      "small",
      "medium",
      "large"
    ]

    value_elicitation_prompt {
      max_attempts = 2

      message {
        content      = "What size pizza would you like?"
        content_type = "PlainText"
      }
    }
  }
}

resource "aws_lex_bot" "order_pizza_bot" {
  name               = "OrderPizzaBot"
  child_directed     = false
  nlu_intent_confidence_threshold = 0.5

  abort_statement {
    message {
      content      = "Sorry, I am not able to assist at this time."
      content_type = "PlainText"
    }
  }

  clarification_prompt {
    max_attempts = 2

    message {
      content      = "I didn't understand you, what would you like to do?"
      content_type = "PlainText"
    }
  }

  intent {
    intent_name    = aws_lex_intent.order_pizza_intent.name
    intent_version = "$LATEST"
  }
}
```

This configuration sets up the necessary AWS Lex resources to create a bot that can order pizzas. The intent specifies the possible utterances and the fulfillment activity, while the bot ties the intent to the bot's functionality and sets the NLU confidence threshold.

