### Description
This Terraform program creates a basic Amazon Kinesis V2 Analytics Application to manage a SQL application. It includes the necessary IAM role with the appropriate permissions and configures the Kinesis Analytics application with a simple SQL query.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Kinesis Analytics
resource "aws_iam_role" "kinesis_analytics_role" {
  name = "kinesis-analytics-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
      }
    ]
  })

  permissions_boundary = "arn:aws:iam::aws:policy/service-role/KinesisAnalyticsServiceRole"

  tags = {
    Name = "kinesis-analytics-role"
  }
}

# CloudWatch Log Group and Log Stream for logging
resource "aws_cloudwatch_log_group" "kinesis_analytics_logs" {
  name = "/aws/kinesis-analytics/sql-application"
}

resource "aws_cloudwatch_log_stream" "kinesis_analytics_log_stream" {
  name           = "sql-application-log-stream"
  log_group_name = aws_cloudwatch_log_group.kinesis_analytics_logs.name
}

# Kinesis Analytics V2 Application
resource "aws_kinesisanalyticsv2_application" "kinesis_analytics_app" {
  name                   = "sql-application"
  runtime_environment    = "SQL-1_0"
  service_execution_role = aws_iam_role.kinesis_analytics_role.arn

  application_configuration {
    application_code_configuration {
      code_content {
        text_content = "SELECT 1;"
      }

      code_content_type = "PLAINTEXT"
    }

    sql_application_configuration {
      input {
        name_prefix = "PREFIX_1"

        input_schema {
          record_column {
            name     = "COLUMN_1"
            sql_type = "VARCHAR(8)"
            mapping  = "MAPPING-1"
          }

          record_column {
            name     = "COLUMN_2"
            sql_type = "DOUBLE"
          }

          record_encoding = "UTF-8"

          record_format {
            record_format_type = "CSV"

            mapping_parameters {
              csv_mapping_parameters {
                record_column_delimiter = ","
                record_row_delimiter    = "\n"
              }
            }
          }
        }

        kinesis_streams_input {
          resource_arn = "arn:aws:kinesis:us-west-2:123456789012:stream/example-kinesis-stream"
        }
      }

      output {
        name = "OUTPUT_1"

        destination_schema {
          record_format_type = "JSON"
        }

        lambda_output {
          resource_arn = "arn:aws:lambda:us-west-2:123456789012:function/example-lambda-function"
        }
      }
    }
  }

  cloudwatch_logging_options {
    log_stream_arn = aws_cloudwatch_log_stream.kinesis_analytics_log_stream.arn
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **IAM Role**: An IAM role named `kinesis-analytics-role` is created with a trust policy allowing Kinesis Analytics to assume the role. The role is tagged for identification.
3. **CloudWatch Logs**: A CloudWatch log group and log stream are created for logging the application's activities.
4. **Kinesis Analytics Application**: A Kinesis Analytics V2 application is created with a SQL runtime environment. The application is configured with a simple SQL query and includes input and output configurations. The input is configured to read from a Kinesis stream, and the output is configured to send data to a Lambda function. The application logs are directed to the previously created CloudWatch log stream.

