    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_kendra_index" "kendra_index" {
  name     = "my-kendra-index"
  role_arn = aws_iam_role.kendra_role.arn

  tags = {
    Name = "My Kendra Index"
  }
}

resource "aws_kendra_data_source" "kendra_data_source" {
  index_id = aws_kendra_index.kendra_index.id
  name     = "my-kendra-data-source"
  type     = "WEBCRAWLER"
  role_arn = aws_iam_role.kendra_role.arn

  configuration {
    web_crawler_configuration {
      urls {
        seed_url_configuration {
          seed_urls = ["https://example.com"]
        }
      }
    }
  }

  lifecycle {
    ignore_changes = [configuration]
  }

  provisioner "local-exec" {
    command = <<EOT
aws kendra update-data-source \
  --id ${aws_kendra_data_source.kendra_data_source.data_source_id} \
  --index-id ${aws_kendra_data_source.kendra_data_source.index_id} \
  --configuration '{
    "WebCrawlerConfiguration": {
      "ProxyConfiguration": {
        "Host": "proxy.example.com",
        "Port": 8080,
        "Credentials": "arn:aws:secretsmanager:us-west-2:123456789012:secret:my-proxy-credentials"
      }
    }
  }'
EOT
  }
}
```

This configuration ensures that the Kendra data source is created with the necessary proxy settings by using a local-exec provisioner to update the data source after its initial creation. The IAM role and Kendra index are also properly defined and linked.

