This Terraform script creates an AWS EKS cluster named "example" and adds the "vpc-cni" addon to it. The script also defines an IAM role required for the EKS cluster to operate. The dependencies between the resources are preserved to ensure proper deployment.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for EKS Cluster
resource "aws_iam_role" "eks_cluster_role" {
  name = "eks-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      },
    ]
  })
}

# Attach necessary policies to the IAM role
resource "aws_iam_role_policy_attachment" "eks_cluster_attach_AmazonEKSClusterPolicy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster_role.name
}

resource "aws_iam_role_policy_attachment" "eks_cluster_attach_AmazonEKSWorkerNodePolicy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.eks_cluster_role.name
}

resource "aws_iam_role_policy_attachment" "eks_cluster_attach_AmazonEC2ContainerRegistryReadOnly" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  role       = aws_iam_role.eks_cluster_role.name
}

# VPC and Subnets for EKS Cluster
resource "aws_vpc" "example_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "example-vpc"
  }
}

resource "aws_subnet" "example_subnet_az1" {
  vpc_id            = aws_vpc.example_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "example-subnet-az1"
  }
}

resource "aws_subnet" "example_subnet_az2" {
  vpc_id            = aws_vpc.example_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  tags = {
    Name = "example-subnet-az2"
  }
}

# EKS Cluster
resource "aws_eks_cluster" "example_cluster" {
  name     = "example"
  role_arn = aws_iam_role.eks_cluster_role.arn

  vpc_config {
    subnet_ids = [aws_subnet.example_subnet_az1.id, aws_subnet.example_subnet_az2.id]
  }

  # Ensure IAM Role permissions are created before and deleted after EKS Cluster handling
  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_attach_AmazonEKSClusterPolicy,
    aws_iam_role_policy_attachment.eks_cluster_attach_AmazonEKSWorkerNodePolicy,
    aws_iam_role_policy_attachment.eks_cluster_attach_AmazonEC2ContainerRegistryReadOnly,
  ]
}

# EKS Addon
resource "aws_eks_addon" "example_addon" {
  cluster_name = aws_eks_cluster.example_cluster.name
  addon_name   = "vpc-cni"
}
