### Description
This Terraform script creates an AWS EKS cluster named "example" and an EKS node group named "example" linked to the cluster. The node group is configured with specific IAM roles, subnet IDs, and scaling parameters. The script also ensures that the necessary IAM policies are attached to the roles to manage permissions during the lifecycle events of EC2 instances and network interfaces.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for the EKS cluster
resource "aws_iam_role" "example_cluster_role" {
  name = "eks-cluster-example"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "sts:AssumeRole",
          "sts:TagSession"
        ]
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      },
    ]
  })
}

# Attach necessary policies to the EKS cluster role
resource "aws_iam_role_policy_attachment" "cluster_AmazonEKSClusterPolicy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.example_cluster_role.name
}

# Create an IAM role for the EKS node group
resource "aws_iam_role" "example_node_group_role" {
  name = "eks-node-group-example"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "sts:AssumeRole"
        ]
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

# Attach necessary policies to the EKS node group role
resource "aws_iam_role_policy_attachment" "node_group_AmazonEKSWorkerNodePolicy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.example_node_group_role.name
}

resource "aws_iam_role_policy_attachment" "node_group_AmazonEKSCNIPolicy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSCNIPolicy"
  role       = aws_iam_role.example_node_group_role.name
}

resource "aws_iam_role_policy_attachment" "node_group_AmazonEC2ContainerRegistryReadOnly" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  role       = aws_iam_role.example_node_group_role.name
}

# Create a VPC and subnets
resource "aws_vpc" "example_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "example_subnet" {
  vpc_id            = aws_vpc.example_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

# Create an EKS cluster
resource "aws_eks_cluster" "example_cluster" {
  name     = "example"
  role_arn = aws_iam_role.example_cluster_role.arn

  vpc_config {
    subnet_ids = [aws_subnet.example_subnet.id]
  }

  depends_on = [
    aws_iam_role_policy_attachment.cluster_AmazonEKSClusterPolicy,
  ]
}

# Create an EKS node group
resource "aws_eks_node_group" "example_node_group" {
  cluster_name    = aws_eks_cluster.example_cluster.name
  node_role_arn   = aws_iam_role.example_node_group_role.arn
  subnet_ids      = [aws_subnet.example_subnet.id]
  node_group_name = "example"

  scaling_config {
    desired_size = 1
    max_size     = 2
    min_size     = 1
  }

  update_config {
    max_unavailable = 1
  }

  depends_on = [
    aws_iam_role_policy_attachment.node_group_AmazonEKSWorkerNodePolicy,
    aws_iam_role_policy_attachment.node_group_AmazonEKSCNIPolicy,
    aws_iam_role_policy_attachment.node_group_AmazonEC2ContainerRegistryReadOnly,
  ]
}
```

This Terraform script sets up an EKS cluster and node group with the specified configurations and dependencies. It ensures that all necessary IAM roles and policies are in place to manage the EKS resources effectively.

