### Description
This Terraform configuration sets up an AWS IAM role named 'eks-cluster' for an Amazon EKS cluster. The IAM role's assume role policy allows access for EKS services, and the AmazonEKSClusterPolicy is attached to this role. Additionally, it creates an AWS EKS cluster with a specified name and version, attaches it to a subnet and VPC in the `us-east-1` region, and ensures proper dependency handling for the IAM role's policy attachment during EKS cluster creation. The EKS cluster's endpoint private access is set to false, and endpoint public access is set to true.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# Create an IAM role for the EKS cluster
resource "aws_iam_role" "eks_cluster_role" {
  name = "eks-cluster"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "sts:AssumeRole",
          "sts:TagSession"
        ]
        Effect = "Allow"
        Principal = {
          Service = [
            "eks.amazonaws.com",
            "ec2.amazonaws.com"
          ]
        }
      },
    ]
  })
}

# Attach the AmazonEKSClusterPolicy to the IAM role
resource "aws_iam_role_policy_attachment" "eks_cluster_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster_role.name
}

# Create a subnet for the EKS cluster
resource "aws_subnet" "eks_subnet" {
  vpc_id            = "vpc-12345678"  # Replace with your VPC ID
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

# Create an EKS cluster
resource "aws_eks_cluster" "eks_cluster" {
  name     = "my-eks-cluster"
  role_arn = aws_iam_role.eks_cluster_role.arn

  vpc_config {
    subnet_ids = [aws_subnet.eks_subnet.id]
    endpoint_private_access = false
    endpoint_public_access  = true
  }

  # Ensure that IAM Role permissions are created before and deleted
  # after EKS Cluster handling. Otherwise, EKS will not be able to
  # properly delete EKS managed EC2 infrastructure such as Security Groups.
  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy_attachment,
  ]
}
```

### Notes
- Replace `"vpc-12345678"` with the actual VPC ID where you want to create the subnet.
- Ensure that the subnet CIDR block and availability zone are appropriate for your VPC and region.
- The EKS cluster name `"my-eks-cluster"` can be customized as needed.

