### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "custom_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "CustomVPC"
  }
}

resource "aws_subnet" "subnet_us_east_1a" {
  vpc_id            = aws_vpc.custom_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
  tags = {
    Name = "SubnetUS-East-1a"
  }
}

resource "aws_subnet" "subnet_us_east_1b" {
  vpc_id            = aws_vpc.custom_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-1b"
  tags = {
    Name = "SubnetUS-East-1b"
  }
}

resource "aws_eip" "eip_us_east_1a" {
  vpc = true
}

resource "aws_eip" "eip_us_east_1b" {
  vpc = true
}

resource "aws_instance" "ec2_instance_us_east_1a" {
  ami                    = data.aws_ami.amazon_linux_2.id
  instance_type          = "t2.micro"
  subnet_id              = aws_subnet.subnet_us_east_1a.id
  associate_public_ip_address = true

  ebs_block_device {
    device_name = "/dev/sda1"
    volume_size = 50
  }

  tags = {
    Name = "EC2InstanceUS-East-1a"
  }
}

resource "aws_instance" "ec2_instance_us_east_1b" {
  ami                    = data.aws_ami.amazon_linux_2.id
  instance_type          = "t2.micro"
  subnet_id              = aws_subnet.subnet_us_east_1b.id
  associate_public_ip_address = true

  ebs_block_device {
    device_name = "/dev/sda1"
    volume_size = 50
  }

  tags = {
    Name = "EC2InstanceUS-East-1b"
  }
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}
```

This configuration ensures that the EC2 instances are correctly associated with the subnets and have the necessary EBS volumes attached. The Elastic IPs are also associated with the instances for public access.

