### Description
The Terraform program defines an AWS Lambda function along with an IAM role and policy required for its execution. It also creates an alias for the Lambda function. The configuration includes a provider setup for AWS, specifying the region as "us-west-2". The Lambda function is configured with a handler, runtime, and environment variables. The IAM role has an assume role policy that allows Lambda to assume the role, and the IAM policy grants permissions for logging. The Lambda alias points to the latest version of the Lambda function.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Lambda Execution
resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Policy for Lambda Execution
resource "aws_iam_policy" "lambda_policy" {
  name        = "lambda_policy"
  description = "Policy for Lambda execution"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "lambda_policy_attachment" {
  policy_arn = aws_iam_policy.lambda_policy.arn
  role       = aws_iam_role.lambda_execution_role.name
}

# Lambda Function
resource "aws_lambda_function" "lambda_function" {
  function_name = "my_lambda_function"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"

  filename         = "lambda_function_payload.zip"
  source_code_hash = filebase64sha256("lambda_function_payload.zip")

  environment {
    variables = {
      NAME = "World"
    }
  }
}

# Lambda Alias
resource "aws_lambda_alias" "lambda_alias" {
  name             = "my_lambda_alias"
  function_name    = aws_lambda_function.lambda_function.function_name
  function_version = "$LATEST"
  description      = "Alias for my Lambda function"
}
```

This configuration ensures that the Lambda function and its alias are correctly set up with the necessary IAM role and policy. The `source_code_hash` is calculated using the `filebase64sha256` function, which requires the file `lambda_function_payload.zip` to exist in the same directory as the Terraform configuration.

