```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "sagemaker_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "sagemaker-vpc"
  }
}

resource "aws_subnet" "sagemaker_subnet" {
  vpc_id                  = aws_vpc.sagemaker_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name = "sagemaker-subnet"
  }
}

resource "aws_iam_role" "sagemaker_execution_role" {
  name = "sagemaker-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "sagemaker-execution-role"
  }
}

resource "aws_sagemaker_domain" "sagemaker_domain" {
  auth_mode   = "IAM"
  domain_name = "my-sagemaker-domain"
  vpc_id      = aws_vpc.sagemaker_vpc.id
  subnet_ids  = [aws_subnet.sagemaker_subnet.id]

  default_user_settings {
    execution_role = aws_iam_role.sagemaker_execution_role.arn
  }

  tags = {
    Name = "my-sagemaker-domain"
  }
}
```

This Terraform configuration includes:
1. An AWS provider configured for the `us-west-2` region.
2. A VPC (`aws_vpc`) with a CIDR block of `10.0.0.0/16`.
3. A subnet (`aws_subnet`) within the VPC with a CIDR block of `10.0.1.0/24`.
4. An IAM role (`aws_iam_role`) with an assume role policy allowing SageMaker to assume the role.
5. A SageMaker domain (`aws_sagemaker_domain`) configured with the IAM role and VPC/subnet details.

This setup ensures that all required dependencies are met for creating a SageMaker domain within a VPC.

