### Description

This Terraform configuration creates an AWS SageMaker domain and a user profile within that domain. The domain is configured with basic settings, including the authentication mode, domain name, VPC ID, and subnet IDs. The user profile is associated with the domain and includes user-specific settings such as the execution role.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for execution
resource "aws_iam_role" "sagemaker_execution_role" {
  name = "sagemaker-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })
}

# Attach policies to the IAM role
resource "aws_iam_role_policy_attachment" "sagemaker_full_access" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonSageMakerFullAccess"
  role       = aws_iam_role.sagemaker_execution_role.name
}

# Create a VPC and subnets
resource "aws_vpc" "sagemaker_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "sagemaker_subnet_1" {
  vpc_id     = aws_vpc.sagemaker_vpc.id
  cidr_block = "10.0.1.0/24"
}

resource "aws_subnet" "sagemaker_subnet_2" {
  vpc_id     = aws_vpc.sagemaker_vpc.id
  cidr_block = "10.0.2.0/24"
}

# Create a SageMaker domain
resource "aws_sagemaker_domain" "sagemaker_domain" {
  auth_mode   = "IAM"
  domain_name = "example-domain"
  vpc_id      = aws_vpc.sagemaker_vpc.id
  subnet_ids  = [aws_subnet.sagemaker_subnet_1.id, aws_subnet.sagemaker_subnet_2.id]

  default_user_settings {
    execution_role = aws_iam_role.sagemaker_execution_role.arn
  }
}

# Create a SageMaker user profile
resource "aws_sagemaker_user_profile" "sagemaker_user_profile" {
  domain_id         = aws_sagemaker_domain.sagemaker_domain.id
  user_profile_name = "example-user-profile"

  user_settings {
    execution_role = aws_iam_role.sagemaker_execution_role.arn
  }
}
```

This configuration sets up a SageMaker domain with the necessary IAM role, VPC, and subnets. It then creates a user profile within that domain, associating it with the previously defined execution role.

