LLM Output #0:
### Description
This Terraform configuration creates a DAX (DynamoDB Accelerator) cluster with the specified node type (`dax.r4.large`) and replication factor (`1`). It also sets up an IAM role and a parameter group required by the DAX cluster. The IAM role is configured to allow DAX to access DynamoDB, and the parameter group is left customizable with specific parameters as needed.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# IAM Role for DAX to access DynamoDB
resource "aws_iam_role" "dax_role" {
  name = "dax-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dax.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy to allow DAX to access DynamoDB
resource "aws_iam_policy" "dax_dynamodb_access_policy" {
  name        = "dax-dynamodb-access-policy"
  description = "Policy to allow DAX to access DynamoDB"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:UpdateItem",
          "dynamodb:DeleteItem",
          "dynamodb:BatchGetItem",
          "dynamodb:BatchWriteItem",
          "dynamodb:Query",
          "dynamodb:Scan",
          "dynamodb:ConditionCheckItem"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "dax_dynamodb_access" {
  role       = aws_iam_role.dax_role.name
  policy_arn = aws_iam_policy.dax_dynamodb_access_policy.arn
}

# DAX Parameter Group
resource "aws_dax_parameter_group" "dax_param_group" {
  name = "dax-param-group"

  parameters {
    name  = "query-ttl-millis"
    value = "100000"
  }

  parameters {
    name  = "record-ttl-millis"
    value = "100000"
  }
}

# DAX Cluster
resource "aws_dax_cluster" "dax_cluster_example" {
  cluster_name       = "dax-cluster-example"
  iam_role_arn       = aws_iam_role.dax_role.arn
  node_type          = "dax.r4.large"
  replication_factor = 1
  parameter_group_name = aws_dax_parameter_group.dax_param_group.name

  depends_on = [
    aws_iam_role.dax_role,
    aws_dax_parameter_group.dax_param_group
  ]
}
```

This configuration sets up the necessary resources to create a DAX cluster with the specified parameters. The IAM role and policy ensure that the DAX cluster has the necessary permissions to access DynamoDB, and the parameter group allows for customization of DAX settings.

