  availability_zone = data.aws_availability_zones.azs.names[1]
  cidr_block        = "10.0.2.0/24"
  vpc_id            = aws_vpc.vpc.id
}

resource "aws_subnet" "subnet_az3" {
  availability_zone = data.aws_availability_zones.azs.names[2]
  cidr_block        = "10.0.3.0/24"
  vpc_id            = aws_vpc.vpc.id
}

resource "aws_security_group" "security_group" {
  vpc_id = aws_vpc.vpc.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_kms_key" "kms_key" {
  description             = "KMS key for MSK encryption"
  deletion_window_in_days = 10
}

resource "aws_cloudwatch_log_group" "cloudwatch_log_group" {
  name = "msk_broker_logs"
}

resource "aws_iam_role" "msk_monitoring_role" {
  name = "msk_monitoring_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "msk.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_monitoring_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEKSClusterPolicy"
  role       = aws_iam_role.msk_monitoring_role.name
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "2.8.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = [
      aws_subnet.subnet_az1.id,
      aws_subnet.subnet_az2.id,
      aws_subnet.subnet_az3.id,
    ]
    instance_type = "m5.large"
    security_groups = [aws_security_group.security_group.id]
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.kms_key.arn
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.cloudwatch_log_group.name
      }
    }
  }

  tags = {
    Name = "MyMSKCluster"
  }
}

resource "aws_route53_zone" "route53_zone" {
  name = "example.com"
}

resource "aws_route53_query_log" "route53_query_log" {
  cloudwatch_log_group_arn = aws_cloudwatch_log_group.cloudwatch_log_group.arn
  zone_id                  = aws_route53_zone.route53_zone.zone_id
}
