LLM Output #0:
### Description

The Terraform program defines a managed Amazon MSK (Managed Streaming for Apache Kafka) cluster in the `us-east-1` region. The cluster is deployed within a VPC with three subnets across different availability zones. It uses a security group to control inbound and outbound traffic. Additionally, the cluster is configured to log its broker logs to an S3 bucket.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "msk_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "msk-vpc"
  }
}

data "aws_availability_zones" "azs" {
  state = "available"
}

resource "aws_subnet" "msk_subnet_az1" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.azs.names[0]
  tags = {
    Name = "msk-subnet-az1"
  }
}

resource "aws_subnet" "msk_subnet_az2" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.azs.names[1]
  tags = {
    Name = "msk-subnet-az2"
  }
}

resource "aws_subnet" "msk_subnet_az3" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = data.aws_availability_zones.azs.names[2]
  tags = {
    Name = "msk-subnet-az3"
  }
}

resource "aws_security_group" "msk_sg" {
  vpc_id = aws_vpc.msk_vpc.id
  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "msk-sg"
  }
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = [
      aws_subnet.msk_subnet_az1.id,
      aws_subnet.msk_subnet_az2.id,
      aws_subnet.msk_subnet_az3.id,
    ]
    instance_type = "m5.large"
    security_groups = [aws_security_group.msk_sg.id]
  }

  logging_info {
    broker_logs {
      s3 {
        enabled = true
        bucket  = aws_s3_bucket.msk_logs_bucket.id
        prefix  = "logs/"
      }
    }
  }

  tags = {
    Name = "my-msk-cluster"
  }
}

resource "aws_s3_bucket" "msk_logs_bucket" {
  bucket = "msk-logs-bucket-${random_string.suffix.result}"
  acl    = "private"
  tags = {
    Name = "msk-logs-bucket"
  }
}

resource "aws_s3_bucket_logging" "msk_bucket_logging" {
  bucket        = aws_msk_cluster.msk_cluster.name
  target_bucket = aws_s3_bucket.msk_logs_bucket.id
  target_prefix = "msk-logs/"
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}
```

This configuration ensures that the MSK cluster is properly set up with the necessary VPC, subnets, security group, and logging to an S3 bucket. The `random_string` resource is used to generate a unique suffix for the S3 bucket name.

