```hcl
provider "aws" {
  region = "us-east-1"
}

# Create a VPC
resource "aws_vpc" "main_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "msk-vpc"
  }
}

# Create subnets in different availability zones
data "aws_availability_zones" "azs" {
  state = "available"
}

resource "aws_subnet" "subnet_az1" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = element(data.aws_availability_zones.azs.names, 0)
  tags = {
    Name = "msk-subnet-az1"
  }
}

resource "aws_subnet" "subnet_az2" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = element(data.aws_availability_zones.azs.names, 1)
  tags = {
    Name = "msk-subnet-az2"
  }
}

resource "aws_subnet" "subnet_az3" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = element(data.aws_availability_zones.azs.names, 2)
  tags = {
    Name = "msk-subnet-az3"
  }
}

# Create a security group for the MSK cluster
resource "aws_security_group" "msk_sg" {
  vpc_id = aws_vpc.main_vpc.id
  name   = "msk-security-group"
  description = "Security group for MSK cluster"
  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "msk-sg"
  }
}

# Create an IAM role for Kinesis Firehose
data "aws_iam_policy_document" "firehose_assume_role_policy" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["firehose.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "firehose_role" {
  name               = "msk-firehose-role"
  assume_role_policy = data.aws_iam_policy_document.firehose_assume_role_policy.json
}

# Attach policies to the IAM role
resource "aws_iam_role_policy_attachment" "firehose_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonKinesisFirehoseFullAccess"
  role       = aws_iam_role.firehose_role.name
}

# Create the MSK cluster
resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "managed-msk-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = [
      aws_subnet.subnet_az1.id,
      aws_subnet.subnet_az2.id,
      aws_subnet.subnet_az3.id,
    ]
    instance_type = "kafka.m5.large"
    security_groups = [aws_security_group.msk_sg.id]
  }

  logging_info {
    broker_logs {
      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.kinesis_firehose_stream.name
      }
    }
  }

  tags = {
    Name = "managed-msk-cluster"
  }
}

# Create the Kinesis Firehose delivery stream
resource "aws_kinesis_firehose_delivery_stream" "kinesis_firehose_stream" {
  name        = "msk-source-delivery-stream"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn   = aws_iam_role.firehose_role.arn
    bucket_arn = "arn:aws:s3:::msk-broker-logs-bucket"
  }

  tags = {
    Name = "msk-source-delivery-stream"
  }
}
```

