### Description
This Terraform configuration creates a managed Amazon MSK (Managed Streaming for Apache Kafka) cluster with JMX Exporter and Node Exporter enabled. The configuration includes the necessary subnets, security groups, and MSK cluster settings. The MSK cluster is configured to use three subnets across different availability zones, and a security group is set up to allow necessary traffic.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet_az1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet_az2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_subnet" "subnet_az3" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = "us-west-2c"
}

resource "aws_security_group" "kafka_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = [
      aws_subnet.subnet_az1.id,
      aws_subnet.subnet_az2.id,
      aws_subnet.subnet_az3.id,
    ]
    instance_type = "kafka.m5.large"
    security_groups = [
      aws_security_group.kafka_sg.id,
    ]
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **VPC**: A VPC is created with a CIDR block of `10.0.0.0/16`.
- **Subnets**: Three subnets are created in different availability zones (`us-west-2a`, `us-west-2b`, `us-west-2c`) within the VPC.
- **Security Group**: A security group is created to allow inbound traffic on port 9092 for Kafka and outbound traffic on all ports.
- **MSK Cluster**: An MSK cluster is created with the specified name, Kafka version, and number of broker nodes. The cluster is configured to use the three subnets and the security group. JMX Exporter and Node Exporter are enabled for monitoring.

