### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-1"
}

provider "aws" {
  alias  = "us_west_2"
  region = "us-west-2"
}

resource "aws_dynamodb_table" "dynamodb_table_us_west_1" {
  name           = "MyDynamoDBTable"
  hash_key       = "id"
  billing_mode   = "PAY_PER_REQUEST"
