### Description
This Terraform configuration creates a DAX (DynamoDB Accelerator) cluster. It includes the necessary IAM role and parameter group required by the DAX cluster. The IAM role is granted permissions to access DynamoDB, and the parameter group is configured with specific parameters.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for DAX to access DynamoDB
resource "aws_iam_role" "dax_role" {
  name = "dax-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dax.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Policy for DAX to access DynamoDB
resource "aws_iam_policy" "dax_policy" {
  name        = "dax-dynamodb-access-policy"
  description = "Policy allowing DAX to access DynamoDB"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "dynamodb:*",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeNetworkInterfaces",
          "ec2:CreateNetworkInterface",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeRouteTables",
          "cloudwatch:GetMetricStatistics",
          "cloudwatch:ListMetrics",
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "*"
      },
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "dax_policy_attachment" {
  role       = aws_iam_role.dax_role.name
  policy_arn = aws_iam_policy.dax_policy.arn
}

# DAX Parameter Group
resource "aws_dax_parameter_group" "dax_param_group" {
  name = "dax-param-group"

  parameters {
    name  = "query-ttl-millis"
    value = "100000"
  }

  parameters {
    name  = "record-ttl-millis"
    value = "100000"
  }
}

# DAX Cluster
resource "aws_dax_cluster" "dax_cluster_example" {
  cluster_name       = "dax-cluster-example"
  iam_role_arn       = aws_iam_role.dax_role.arn
  node_type          = "dax.r4.large"
  replication_factor = 1
  parameter_group_name = aws_dax_parameter_group.dax_param_group.name

  depends_on = [
    aws_iam_role.dax_role,
    aws_dax_parameter_group.dax_param_group
  ]
}
```

This configuration sets up a DAX cluster with the necessary IAM role and parameter group. The IAM role is granted permissions to access DynamoDB, and the parameter group is configured with specific parameters to optimize the DAX cluster's performance.

