### Description

This Terraform configuration sets up an S3 bucket with a custom Time to Live (TTL) attribute for data expiration. It includes an IAM role required for executing a Data Lifecycle Manager (DLM) lifecycle policy, which manages the expiration of objects in the S3 bucket. The configuration ensures that the IAM role has the necessary permissions and that the lifecycle policy is correctly linked to the S3 bucket.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an S3 bucket
resource "aws_s3_bucket" "my_s3_bucket" {
  bucket = "my-custom-ttl-bucket"
  acl    = "private"

  tags = {
    Name        = "Custom TTL Bucket"
    Environment = "Dev"
  }
}

# Create an IAM role for DLM lifecycle policy execution
resource "aws_iam_role" "dlm_lifecycle_role" {
  name = "dlm-lifecycle-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "dlm.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Attach an inline policy to the IAM role
resource "aws_iam_role_policy" "dlm_lifecycle_policy" {
  name   = "dlm-lifecycle-policy"
  role   = aws_iam_role.dlm_lifecycle_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:CreateSnapshot",
          "ec2:CreateSnapshots",
          "ec2:DeleteSnapshot",
          "ec2:DescribeInstances",
          "ec2:DescribeVolumes",
          "ec2:DescribeSnapshots",
          "ec2:CreateTags"
        ]
        Resource = "*"
      }
    ]
  })
}

# Create a DLM lifecycle policy
resource "aws_dlm_lifecycle_policy" "dlm_lifecycle_policy" {
  description        = "Custom TTL DLM lifecycle policy"
  execution_role_arn = aws_iam_role.dlm_lifecycle_role.arn
  state              = "ENABLED"

  policy_details {
    resource_types = ["VOLUME"]

    schedule {
      name = "Daily Snapshots"

      create_rule {
        interval      = 24
        interval_unit = "HOURS"
        times         = ["23:45"]
      }

      retain_rule {
        count = 14
      }

      tags_to_add = {
        SnapshotCreator = "DLM"
      }

      copy_tags = false
    }

    target_tags = {
      Snapshot = "true"
    }
  }
}

# Configure the S3 bucket lifecycle
resource "aws_s3_bucket_lifecycle_configuration" "my_s3_bucket_lifecycle" {
  bucket = aws_s3_bucket.my_s3_bucket.id

  rule {
    id     = "ExpireObjects"
    status = "Enabled"

    expiration {
      days = 30
    }
  }
}
```

This configuration creates an S3 bucket, an IAM role with the necessary permissions, and a DLM lifecycle policy to manage snapshots. Additionally, it configures the S3 bucket to expire objects after 30 days.

