### Description
The Terraform program configures a DynamoDB table with server-side encryption enabled using a KMS key. The KMS key is created with specific policies to allow the DynamoDB service to use it for encryption. The configuration includes a provider setup for AWS in the `us-west-2` region.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_kms_key" "example_kms_key" {
  description             = "KMS key for DynamoDB encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 10
  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-default-1"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow use of the key"
        Effect = "Allow"
        Principal = {
          Service = "dynamodb.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext"
        ],
        Resource = "*"
      }
    ]
  })
}

data "aws_caller_identity" "current" {}

resource "aws_dynamodb_table" "example_dynamodb_table" {
  name           = "example_table"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.example_kms_key.arn
  }
}
```

This configuration ensures that the DynamoDB table is encrypted using the specified KMS key, and the KMS key policy allows the DynamoDB service to use it for encryption. The `data.aws_caller_identity.current` resource is used to fetch the current AWS account ID, which is necessary for the KMS key policy.

