### Description
This Terraform configuration creates an AWS Redshift cluster with specific parameters and sets up notifications for events associated with the parameter group using an SNS topic. The configuration includes:

1. **AWS SNS Topic**: A topic to receive Redshift event notifications.
2. **AWS Redshift Parameter Group**: A parameter group with example parameters.
3. **AWS Redshift Cluster**: A Redshift cluster associated with the parameter group.
4. **AWS Redshift Event Subscription**: A subscription to receive events related to the Redshift cluster.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_sns_topic" "redshift_events_topic" {
  name = "redshift-events-topic"
}

resource "aws_redshift_parameter_group" "example_parameter_group" {
  name   = "example-parameter-group"
  family = "redshift-1.0"

  parameter {
    name  = "require_ssl"
    value = "true"
  }

  parameter {
    name  = "query_group"
    value = "example"
  }

  parameter {
    name  = "enable_user_activity_logging"
    value = "true"
  }
}

resource "aws_redshift_cluster" "example_redshift_cluster" {
  cluster_identifier = "example-cluster"
  database_name      = "mydb"
  master_username    = "exampleuser"
  master_password    = "Mustbe8characters"
  node_type          = "dc1.large"
  cluster_parameter_group_name = aws_redshift_parameter_group.example_parameter_group.name
}

resource "aws_redshift_event_subscription" "redshift_event_subscription" {
  name          = "redshift-event-sub"
  sns_topic_arn = aws_sns_topic.redshift_events_topic.arn
  source_type   = "cluster"
  source_ids    = [aws_redshift_cluster.example_redshift_cluster.id]
  severity      = "INFO"

  event_categories = [
    "configuration",
    "management",
    "monitoring",
    "security"
  ]

  tags = {
    Name = "default"
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **SNS Topic**: An SNS topic named `redshift-events-topic` is created to receive notifications.
- **Redshift Parameter Group**: A parameter group named `example-parameter-group` is created with specific parameters.
- **Redshift Cluster**: A Redshift cluster named `example-cluster` is created with the specified database name, username, password, and node type. It is associated with the previously created parameter group.
- **Redshift Event Subscription**: An event subscription named `redshift-event-sub` is created to subscribe to various event categories for the Redshift cluster, sending notifications to the SNS topic.

