### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"  # Specify the desired AWS region
}

resource "aws_s3_bucket" "mybucket" {
  bucket = "mybucket"
  acl    = "private"     # Set the appropriate ACL
}

resource "aws_s3_object" "mybucket_object" {
  bucket = aws_s3_bucket.mybucket.bucket
  key    = "path/to/file"
