### Description
This Terraform configuration sets up an infrastructure for an autograder for a CS class. It uses AWS CodeBuild to run students' code stored on GitHub and AWS S3 to store the results. The configuration includes an IAM role with the necessary permissions for CodeBuild to interact with GitHub and S3.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for CodeBuild
resource "aws_iam_role" "autograder_codebuild_role" {
  name = "autograder-codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  inline_policy {
    name = "autograder-policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect = "Allow"
          Action = [
            "logs:CreateLogGroup",
            "logs:CreateLogStream",
            "logs:PutLogEvents"
          ]
          Resource = "*"
        },
        {
          Effect = "Allow"
          Action = [
            "s3:GetObject",
            "s3:PutObject",
            "s3:ListBucket"
          ]
          Resource = [
            "arn:aws:s3:::autograder-results",
            "arn:aws:s3:::autograder-results/*"
          ]
        },
        {
          Effect = "Allow"
          Action = [
            "codebuild:StartBuild",
            "codebuild:BatchGetBuilds",
            "codebuild:StopBuild"
          ]
          Resource = "*"
        }
      ]
    })
  }
}

# S3 Bucket for storing results
resource "aws_s3_bucket" "autograder_results_bucket" {
