### Description
The Terraform program defines the infrastructure for an autograder system that runs students' code stored on GitHub and stores the results in an AWS S3 bucket. It includes an AWS S3 bucket to store the results, an IAM role and policy for the AWS CodeBuild project, and the CodeBuild project itself configured to pull code from GitHub and execute it.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# S3 Bucket to store the results of the autograder
resource "aws_s3_bucket" "autograder_results_bucket" {
  bucket = "autograder-results-bucket-${random_string.suffix.result}"
  acl    = "private"

  tags = {
    Name        = "AutograderResultsBucket"
    Environment = "Production"
  }
}

# Random string to ensure a unique bucket name
resource "random_string" "suffix" {
  length  = 8
  special = false
}

# IAM Role for the CodeBuild project
resource "aws_iam_role" "autograder_codebuild_role" {
  name = "autograder-codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name        = "AutograderCodeBuildRole"
    Environment = "Production"
  }
}

# IAM Policy for the CodeBuild role
resource "aws_iam_role_policy" "autograder_codebuild_policy" {
  name = "autograder-codebuild-policy"
  role = aws_iam_role.autograder_codebuild_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Effect = "Allow"
        Resource = "${aws_s3_bucket.autograder_results_bucket.arn}/*"
      }
    ]
  })
}

# CodeBuild Project to run students' code
resource "aws_codebuild_project" "autograder_codebuild_project" {
  name          = "autograder-codebuild-project"
  description   = "CodeBuild project for autograding CS class students' code"
  service_role  = aws_iam_role.autograder_codebuild_role.arn
  build_timeout = 60

  artifacts {
    type = "S3"
    location = "${aws_s3_bucket.autograder_results_bucket.bucket}/build-artifacts"
  }

  cache {
    type = "NO_CACHE"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux2-x86_64-standard:4.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }

  source {
    type            = "GITHUB"
    location        = "https://github.com/example/repo.git"
    git_clone_depth = 1
  }

  tags = {
    Name        = "AutograderCodeBuildProject"
    Environment = "Production"
  }
}
```

This configuration ensures that the necessary AWS resources are created to support the autograder system, including a unique S3 bucket for storing results, an IAM role with the appropriate permissions, and a CodeBuild project configured to execute students' code from a GitHub repository.

