  bucket = "cat-pictures-bucket-${random_string.suffix.result}"
  acl    = "private"
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}

# Lambda Function to handle uploading cat pictures
resource "aws_lambda_function" "upload_cat_picture_lambda" {
  function_name = "upload_cat_picture_lambda"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "lambda_function.handler"
  runtime       = "python3.8"
  filename      = "path/to/upload_cat_picture_lambda.zip"

  environment {
    variables = {
      DYNAMODB_TABLE_NAME = aws_dynamodb_table.cat_pictures_table.name
      S3_BUCKET_NAME      = aws_s3_bucket.cat_pictures_bucket.bucket
    }
  }
}

# Lambda Function to provide random cat pictures
