This Terraform configuration provisions an EC2 instance and sets up a daily backup at midnight using AWS Backup. The configuration includes the following resources:
1. **AWS EC2 Instance**: An EC2 instance is provisioned with a specified instance class.
2. **AWS Backup Vault**: A backup vault is created to store the backups.
3. **AWS Backup Plan**: A backup plan is created to schedule daily backups at midnight.
4. **IAM Role**: An IAM role is created with the necessary permissions for backup operations.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "backup_role" {
  name = "backup-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_policy" "backup_policy" {
  name        = "backup-policy"
  description = "Policy for backup operations"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:StartInstances",
          "ec2:StopInstances",
          "ec2:DescribeInstances",
          "ec2:TerminateInstances",
          "ec2:RebootInstances",
          "ec2:DescribeVolumes",
          "ec2:DescribeSnapshots",
          "ec2:CreateSnapshot",
          "ec2:DeleteSnapshot",
          "ec2:CreateTags"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup_policy_attachment" {
  role       = aws_iam_role.backup_role.name
  policy_arn = aws_iam_policy.backup_policy.arn
}

resource "aws_backup_vault" "backup_vault" {
  name = "my-backup-vault"
}

resource "aws_backup_plan" "backup_plan" {
  name = "daily-backup-plan"

  rule {
    rule_name         = "daily-backup-rule"
    target_vault_name = aws_backup_vault.backup_vault.name
    schedule          = "cron(0 0 * * ? *)"  # Daily at midnight

    lifecycle {
      delete_after = 30  # Retain backups for 30 days
    }
  }
}

resource "aws_db_instance" "db_instance" {
