  name               = "backup-role"
  assume_role_policy = data.aws_iam_policy_document.assume_role_policy.json
}

# Attach policies to the IAM role
data "aws_iam_policy_document" "backup_policy" {
  statement {
    effect = "Allow"

    actions = [
      "ec2:CreateSnapshot",
      "ec2:CreateSnapshots",
      "ec2:DeleteSnapshot",
      "ec2:DescribeInstances",
      "ec2:DescribeVolumes",
      "ec2:DescribeSnapshots",
    ]

    resources = ["*"]
  }

  statement {
    effect    = "Allow"
    actions   = ["ec2:CreateTags"]
    resources = ["arn:aws:ec2:*::snapshot/*"]
  }
}

resource "aws_iam_role_policy" "backup_policy" {
  name   = "backup-policy"
  role   = aws_iam_role.backup_role.id
  policy = data.aws_iam_policy_document.backup_policy.json
}

# Create an AWS DLM lifecycle policy
resource "aws_dlm_lifecycle_policy" "dlm_lifecycle_policy" {
  description        = "daily-snapshot-policy"
  execution_role_arn = aws_iam_role.backup_role.arn

  policy_details {
    resource_types = ["VOLUME"]

    schedule {
      name = "daily-snapshot-schedule"

      create_rule {
        interval      = 24
        interval_unit = "HOURS"
        times         = ["23:45"]  # Adjusted to trigger just before midnight
      }

      retain_rule {
        count = 30  # Retain snapshots for 30 days
      }

      tags_to_add = {
        SnapshotCreator = "DLM"
      }

      copy_tags = false
    }

    target_tags = {
      Snapshot = "true"
    }
  }
}

# Variable definition for public key
variable "public_key" {
  description = "The public key material for the EC2 key pair"
  type        = string
  default     = "ssh-rsa AAAAB3NzaC1yc2EAAAADAQABAAABAQC..."
}
