  source_arn    = aws_cloudwatch_event_rule.daily_event_rule.arn
}

resource "aws_cloudwatch_event_target" "daily_event_target" {
  rule      = aws_cloudwatch_event_rule.daily_event_rule.name
  target_id = "daily_lambda_target"
  arn       = aws_lambda_function.daily_lambda_function.arn
}
