### Description
The Terraform program defines the infrastructure for a video streaming site that distributes video content globally using AWS CloudFront, AWS Route53, and AWS S3. The program includes creating an S3 bucket to store video content, a CloudFront distribution to distribute the content, and a Route53 zone with a record pointing to the CloudFront distribution. The configuration ensures that the S3 bucket has the correct permissions for CloudFront to access the content.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# Create an S3 bucket to store video content
resource "aws_s3_bucket" "video_content_bucket" {
  bucket = "video-content-bucket-${var.environment}"
  acl    = "private"

  tags = {
    Name        = "Video Content Bucket"
    Environment = var.environment
  }
}

# Create a CloudFront distribution to distribute the video content
resource "aws_cloudfront_distribution" "video_content_distribution" {
  origin {
    domain_name = aws_s3_bucket.video_content_bucket.bucket_regional_domain_name
    origin_id   = "myS3Origin"
  }

  enabled             = true
  is_ipv6_enabled     = true
  comment             = "Distribution for video content"
  default_root_object = "index.html"

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "myS3Origin"

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
  }

  price_class = "PriceClass_200"

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  tags = {
    Environment = var.environment
  }
}

# Create a Route53 zone for the video streaming site
resource "aws_route53_zone" "video_streaming_zone" {
  name = "video-streaming-site.com"

  tags = {
    Name        = "Video Streaming Site Zone"
    Environment = var.environment
  }
}

# Create a Route53 record to point to the CloudFront distribution
resource "aws_route53_record" "video_streaming_record" {
  zone_id = aws_route53_zone.video_streaming_zone.zone_id
  name    = "www"
  type    = "A"
  ttl     = 300

  alias {
    name                   = aws_cloudfront_distribution.video_content_distribution.domain_name
    zone_id                = aws_cloudfront_distribution.video_content_distribution.hosted_zone_id
    evaluate_target_health = false
  }
}

# Variables
variable "environment" {
  description = "Environment name (e.g., dev, prod)"
  default     = "dev"
}
```

