provider "random" {}

# S3 Bucket to serve as the origin for the CloudFront distribution
resource "aws_s3_bucket" "s3_video_content_bucket" {
  bucket = "video-content-bucket-${random_string.bucket_suffix.result}"
  acl    = "private"
}

# Random string to avoid naming conflicts
resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

# CloudFront Origin Access Control for the S3 bucket
resource "aws_cloudfront_origin_access_control" "s3_origin_access_control" {
  name                              = "s3-origin-access-control"
  description                       = "Managed by Terraform"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

# CloudFront Distribution with S3 bucket as origin
resource "aws_cloudfront_distribution" "s3_video_content_distribution" {
  origin {
    domain_name              = aws_s3_bucket.s3_video_content_bucket.bucket_regional_domain_name
    origin_access_control_id = aws_cloudfront_origin_access_control.s3_origin_access_control.id
    origin_id                = "s3_video_content_origin"
  }

  enabled             = true
  price_class         = "PriceClass_200"

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "s3_video_content_origin"
    viewer_protocol_policy = "allow-all"
  }

  restrictions {
    geo_restriction {
      restriction_type = "whitelist"
      locations        = ["US", "CA", "GB", "DE"]
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

# Route53 Zone for the domain netflix.com
resource "aws_route53_zone" "netflix_com_zone" {
  name = "netflix.com"
}

# First Route53 Record linked to the Route53 hosted zone
resource "aws_route53_record" "netflix_com_record_1" {
  zone_id = aws_route53_zone.netflix_com_zone.zone_id
  name    = "www"
  type    = "A"
  ttl     = 300
  records = ["192.0.2.1"]
}

# Second Route53 Record linked to the Route53 hosted zone
resource "aws_route53_record" "netflix_com_record_2" {
  zone_id = aws_route53_zone.netflix_com_zone.zone_id
  name    = "api"
  type    = "CNAME"
  ttl     = 300
  records = ["api.netflix.com"]
}
```

