    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
    path                = "/"
  }

  tags = {
    Environment = "production"
  }
}

resource "aws_instance" "video_streaming_server_1" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID for t3.micro in us-west-2
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.public_1.id
  vpc_security_group_ids = [aws_security_group.instance_sg.id]

  tags = {
    Name = "video-streaming-server-1"
  }
}

resource "aws_instance" "video_streaming_server_2" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID for t3.micro in us-west-2
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.public_2.id
  vpc_security_group_ids = [aws_security_group.instance_sg.id]

  tags = {
    Name = "video-streaming-server-2"
  }
}

resource "aws_lb_target_group_attachment" "video_streaming_server_1_attachment" {
  target_group_arn = aws_lb_target_group.video_streaming_tg.arn
  target_id        = aws_instance.video_streaming_server_1.id
  port             = 80
}

resource "aws_lb_target_group_attachment" "video_streaming_server_2_attachment" {
  target_group_arn = aws_lb_target_group.video_streaming_tg.arn
  target_id        = aws_instance.video_streaming_server_2.id
  port             = 80
}
