provider "aws" {
  region = "us-west-2"
}

# Create a VPC for the video streaming site
resource "aws_vpc" "video_streaming_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "video-streaming-vpc"
  }
}

# Create a subnet within the VPC
resource "aws_subnet" "video_streaming_subnet" {
  vpc_id                  = aws_vpc.video_streaming_vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-west-2a"
  map_public_ip_on_launch = true
  tags = {
    Name = "video-streaming-subnet"
  }
}

# Create an Application Load Balancer
resource "aws_lb" "video_streaming_lb" {
  name            = "video-streaming-alb"
  internal        = false
  load_balancer_type = "application"
  subnets         = [aws_subnet.video_streaming_subnet.id]
  security_groups = [aws_security_group.video_streaming_sg.id]

  tags = {
    Name = "video-streaming-alb"
  }
}

# Create a target group for the load balancer
resource "aws_lb_target_group" "video_streaming_target_group" {
  name     = "video-streaming-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.video_streaming_vpc.id
  target_type = "instance"

  health_check {
    enabled             = true
    interval            = 30
    path                = "/"
    port                = "traffic-port"
    protocol            = "HTTP"
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Name = "video-streaming-target-group"
  }
}

# Create a security group for the video streaming site
resource "aws_security_group" "video_streaming_sg" {
  name        = "video-streaming-sg"
  description = "Allow HTTP traffic"
  vpc_id      = aws_vpc.video_streaming_vpc.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "video-streaming-sg"
  }
}

# Create multiple EC2 instances for the video streaming site
resource "aws_instance" "video_streaming_server" {
  count         = 3
  ami           = "ami-0c55b159cbfafe1f0" # Example AMI ID
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.video_streaming_subnet.id
  security_groups = [aws_security_group.video_streaming_sg.name]

  tags = {
    Name = "video-streaming-server-${count.index}"
  }
}

# Register EC2 instances with the target group
resource "aws_lb_target_group_attachment" "video_streaming_target_group_attachment" {
  count            = length(aws_instance.video_streaming_server)
  target_group_arn = aws_lb_target_group.video_streaming_target_group.arn
  target_id        = element(aws_instance.video_streaming_server[*].id, count.index)
  port             = 80
}

# Create a Route53 zone for the video streaming site
resource "aws_route53_zone" "video_streaming_zone" {
  name = "video-streaming-site.com"

  tags = {
    Name = "video-streaming-zone"
  }
}

# Create a Route53 record for the video streaming site
resource "aws_route53_record" "video_streaming_record" {
  zone_id = aws_route53_zone.video_streaming_zone.zone_id
  name    = "www.video-streaming-site.com"
  type    = "A"
  records = [aws_lb.video_streaming_lb.dns_name]
  ttl     = 300

  # Removed the unsupported 'tags' argument
}
