provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC where the database will be deployed."
  default     = "vpc-12345678"
}

variable "subnet1_cidr_block" {
  description = "The CIDR block for the first subnet."
  default     = "10.0.1.0/24"
}

variable "subnet2_cidr_block" {
  description = "The CIDR block for the second subnet."
  default     = "10.0.2.0/24"
}

resource "aws_iam_role" "rds_kms_access_role" {
  name = "rds-kms-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_kms_key" "database_encryption_key" {
  description             = "KMS key for encrypting the database instance."
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

resource "aws_security_group" "database_sg" {
  name        = "database-sg"
  description = "Security group for the database instance."
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_subnet" "subnet1" {
  vpc_id            = var.vpc_id
  cidr_block        = var.subnet1_cidr_block
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet2" {
  vpc_id            = var.vpc_id
  cidr_block        = var.subnet2_cidr_block
  availability_zone = "us-west-2b"
}

resource "aws_db_subnet_group" "database_subnet_group" {
  name       = "database-subnet-group"
  subnet_ids = [aws_subnet.subnet1.id, aws_subnet.subnet2.id]
}

resource "aws_db_instance" "secure_postgresql_db" {
  instance_class      = "db.t3.micro"
  engine              = "postgres"
  engine_version      = "13.7"
  allocated_storage   = 20
  storage_type        = "gp2"
  multi_az            = true
  username            = "admin"
  password            = "securepassword"
  db_name             = "mydatabase"
  vpc_security_group_ids = [aws_security_group.database_sg.id]
  db_subnet_group_name = aws_db_subnet_group.database_subnet_group.name
  kms_key_id          = aws_kms_key.database_encryption_key.arn
  backup_retention_period = 7
  storage_encrypted   = true
  publicly_accessible = false

  depends_on = [
    aws_iam_role.rds_kms_access_role,
    aws_kms_key.database_encryption_key,
    aws_security_group.database_sg,
    aws_db_subnet_group.database_subnet_group
  ]
}
