Below is the Terraform HCL program that sets up an AWS environment with a main VPC, two subnets across different availability zones, and a security group to allow database access. It also configures a 500 GB 5.7 MySQL RDS instance with public accessibility, linked to the defined subnets and security group, and outputs the database endpoint for connectivity.

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the main VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_a_cidr_block" {
  description = "CIDR block for Subnet A"
  default     = "10.0.1.0/24"
}

variable "subnet_b_cidr_block" {
  description = "CIDR block for Subnet B"
  default     = "10.0.2.0/24"
}

variable "availability_zone_a" {
  description = "Availability Zone for Subnet A"
  default     = "us-west-2a"
}

variable "availability_zone_b" {
  description = "Availability Zone for Subnet B"
  default     = "us-west-2b"
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "subnet_a" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = var.subnet_a_cidr_block
  availability_zone = var.availability_zone_a
  map_public_ip_on_launch = true
}

resource "aws_subnet" "subnet_b" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = var.subnet_b_cidr_block
  availability_zone = var.availability_zone_b
  map_public_ip_on_launch = true
}

resource "aws_security_group" "db_security_group" {
  vpc_id = aws_vpc.main_vpc.id
  name   = "db-security-group"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "mysql_db_instance" {
  instance_class       = "db.t3.medium"
  allocated_storage    = 500
  engine               = "mysql"
  engine_version       = "5.7"
  username             = "admin"
  password             = "password"
  publicly_accessible  = true
  vpc_security_group_ids = [aws_security_group.db_security_group.id]
  db_subnet_group_name = "default"  # Using the default subnet group for simplicity
}

output "database_endpoint" {
  value = aws_db_instance.mysql_db_instance.endpoint
}
```

