Below is a complete Terraform HCL program that sets up a PostgreSQL database instance in AWS, specifying details like engine version, instance size, storage, and associated networking resources within a custom VPC and subnet. The database allows major version upgrades, automatically does minor version upgrades, and is not publicly accessible.

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC where the database and proxy will be deployed."
  default     = "vpc-12345678"
}

variable "subnet_id" {
  description = "The ID of the subnet where the database and proxy will be deployed."
  default     = "subnet-12345678"
}

variable "security_group_id" {
  description = "The ID of the security group for the database and proxy."
  default     = "sg-12345678"
}

resource "aws_db_instance" "postgresql_db_instance" {
  instance_class           = "db.t3.micro"
  engine                   = "postgres"
  engine_version           = "13.6"
  allocated_storage        = 20
  allow_major_version_upgrade = true
  auto_minor_version_upgrade = true
  db_name                  = "mydatabase"
  username                 = "admin"
  password                 = "securepassword"
  publicly_accessible      = false
  vpc_security_group_ids   = [var.security_group_id]
  db_subnet_group_name     = "mydb_subnet_group"
}

resource "aws_iam_role" "db_proxy_role" {
  name = "db-proxy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_security_group" "db_proxy_sg" {
  name        = "db-proxy-sg"
  description = "Security group for the DB proxy"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_subnet" "db_proxy_subnet" {
  vpc_id            = var.vpc_id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_db_proxy" "postgresql_db_proxy" {
  name               = "my-postgres-proxy"
  engine_family      = "POSTGRESQL"
  role_arn           = aws_iam_role.db_proxy_role.arn
  vpc_subnet_ids     = [var.subnet_id]
  vpc_security_group_ids = [aws_security_group.db_proxy_sg.id]

  auth {
    auth_scheme = "SECRETS"
    secret_arn  = "arn:aws:secretsmanager:us-west-2:123456789012:secret:my-secret"
    username    = "admin"
  }
}
```

This Terraform configuration sets up a PostgreSQL database instance in AWS with the specified requirements. It includes the necessary IAM role, security group, subnet, and DB proxy resources, ensuring proper dependencies and configurations.

