### Description
This Terraform configuration sets up an AWS RDS Aurora MySQL cluster with a proxy for enhanced connection management. It includes the creation of a VPC, subnets, security groups, IAM roles, and a Secrets Manager secret for secure credential storage. The RDS cluster has a backup retention period of 5 days, and the preferred backup window is set from 7 AM to 9 AM.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# VPC
resource "aws_vpc" "rds_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "rds-vpc"
  }
}

# Subnets
resource "aws_subnet" "rds_subnet_1" {
  vpc_id            = aws_vpc.rds_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "rds-subnet-1"
  }
}

resource "aws_subnet" "rds_subnet_2" {
  vpc_id            = aws_vpc.rds_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  tags = {
    Name = "rds-subnet-2"
  }
}

resource "aws_subnet" "rds_subnet_3" {
  vpc_id            = aws_vpc.rds_vpc.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = "us-west-2c"
  tags = {
    Name = "rds-subnet-3"
  }
}

# Security Group
resource "aws_security_group" "rds_sg" {
  vpc_id = aws_vpc.rds_vpc.id
  name   = "rds-sg"
  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "rds-sg"
  }
}

# IAM Role
resource "aws_iam_role" "rds_iam_role" {
  name = "rds-iam-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
  tags = {
    Name = "rds-iam-role"
  }
}

# IAM Policy
resource "aws_iam_policy" "rds_iam_policy" {
  name        = "rds-iam-policy"
  description = "Policy for RDS Aurora MySQL cluster"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
  tags = {
    Name = "rds-iam-policy"
  }
}

# IAM Role Policy Attachment
resource "aws_iam_role_policy_attachment" "attach_rds_policy_to_role" {
  policy_arn = aws_iam_policy.rds_iam_policy.arn
  role       = aws_iam_role.rds_iam_role.name
}

# Secrets Manager Secret
resource "aws_secretsmanager_secret" "rds_secret" {
  name = "rds-secret"
  description = "Secret for RDS Aurora MySQL cluster"
  tags = {
    Name = "rds-secret"
  }
}

# DB Subnet Group
resource "aws_db_subnet_group" "rds_subnet_group" {
  name       = "rds-subnet-group"
  subnet_ids = [aws_subnet.rds_subnet_1.id, aws_subnet.rds_subnet_2.id, aws_subnet.rds_subnet_3.id]
  tags = {
    Name = "rds-subnet-group"
  }
}

# RDS Aurora MySQL Cluster
resource "aws_rds_cluster" "rds_cluster" {
  engine                = "aurora-mysql"
  engine_version        = "8.0.mysql_aurora.3.02.1"
  cluster_identifier    = "aurora-cluster-demo"
  master_username       = "admin"
  master_password       = "securepassword"
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
  db_subnet_group_name  = aws_db_subnet_group.rds_subnet_group.name
  vpc_security_group_ids = [aws_security_group.rds_sg.id]
  iam_roles             = [aws_iam_role.rds_iam_role.arn]
  tags = {
    Name = "aurora-cluster-demo"
  }
}

# DB Proxy
resource "aws_db_proxy" "rds_proxy" {
  name                   = "rds-proxy"
  engine_family          = "MYSQL"
  role_arn               = aws_iam_role.rds_iam_role.arn
  vpc_subnet_ids         = [aws_subnet.rds_subnet_1.id, aws_subnet.rds_subnet_2.id, aws_subnet.rds_subnet_3.id]
  vpc_security_group_ids = [aws_security_group.rds_sg.id]
  auth {
    auth_scheme = "SECRETS"
    secret_arn  = aws_secretsmanager_secret.rds_secret.arn
    username    = "admin"
  }
  tags = {
    Name = "rds-proxy"
  }
}
```

This configuration creates all the necessary resources to set up an AWS RDS Aurora MySQL cluster with a proxy, including VPC, subnets, security groups, IAM roles, and Secrets Manager for secure credential storage. The RDS cluster is configured with a backup retention period of 5 days and a preferred backup window from 7 AM to 9 AM.

