### Description

This Terraform configuration creates an S3 bucket, configures its lifecycle rules to transition objects to S3 Glacier, and sets up an S3 Glacier vault with notifications via an SNS topic. The configuration ensures that the S3 bucket has versioning enabled to support noncurrent version transitions.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "my_s3_bucket" {
  bucket = "my-glacier-lifecycle-bucket"
  acl    = "private"

  versioning {
    enabled = true
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "my_s3_bucket_lifecycle_configuration" {
  bucket = aws_s3_bucket.my_s3_bucket.id

  rule {
    id     = "transition-to-glacier"
    status = "Enabled"

    filter {
      prefix = ""
    }

    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "GLACIER"
    }
  }
}

resource "aws_sns_topic" "my_sns_topic" {
  name = "glacier-vault-notifications"
}

resource "aws_glacier_vault" "my_glacier_vault" {
  name = "my-glacier-vault"

  notification {
    sns_topic = aws_sns_topic.my_sns_topic.arn
    events    = ["ArchiveRetrievalCompleted", "InventoryRetrievalCompleted"]
  }
}
```

### Explanation

