### Description
This Terraform configuration creates an S3 Glacier vault named `my_archive` with an access policy that allows read-only access to the Glacier service. It also sets up an SNS topic for notifications related to the Glacier vault and locks the vault with a policy.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_sns_topic" "glacier_sns_topic" {
  name = "glacier-sns-topic"
}

data "aws_iam_policy_document" "my_archive" {
  statement {
    sid    = "add-read-only-perm"
    effect = "Allow"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = [
      "glacier:InitiateJob",
      "glacier:GetJobOutput",
    ]

    resources = ["arn:aws:glacier:${var.region}:${var.account_id}:vaults/my_archive"]
  }
}

resource "aws_glacier_vault" "my_archive" {
  name = "my_archive"

  notification {
    sns_topic = aws_sns_topic.glacier_sns_topic.arn
    events    = ["ArchiveRetrievalCompleted", "InventoryRetrievalCompleted"]
  }

  access_policy = data.aws_iam_policy_document.my_archive.json

  tags = {
    Test = "MyArchive"
  }
}

resource "aws_glacier_vault_lock" "my_archive_lock" {
  complete_lock = true
  policy        = data.aws_iam_policy_document.my_archive_lock.json
  vault_name    = aws_glacier_vault.my_archive.name
}

data "aws_iam_policy_document" "my_archive_lock" {
  statement {
    sid    = "lock-policy"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = [
      "glacier:DeleteVaultLock",
      "glacier:CompleteVaultLock",
    ]

    resources = ["arn:aws:glacier:${var.region}:${var.account_id}:vaults/my_archive"]
  }
}

variable "region" {
  description = "AWS region"
  default     = "us-east-1"
}

variable "account_id" {
  description = "AWS account ID"
  default     = "123456789012"
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **SNS Topic**: An SNS topic named `glacier-sns-topic` is created for notifications.
3. **IAM Policy Document for Glacier Vault**: An IAM policy document is created to allow read-only access to the Glacier vault.
4. **Glacier Vault**: A Glacier vault named `my_archive` is created with the specified access policy and notification settings.
5. **IAM Policy Document for Glacier Vault Lock**: Another IAM policy document is created to deny certain actions on the Glacier vault lock.
6. **Glacier Vault Lock**: The Glacier vault is locked with the specified policy, ensuring that it cannot be deleted or modified.

This configuration ensures that the Glacier vault is properly secured and monitored with notifications.

