### Description

This Terraform program creates an Application Load Balancer (ALB) with two public subnets, a target group, and a listener that forwards traffic to the target group. The ALB is configured to use the `application` type, and the listener is set up to handle HTTP traffic on port 80.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "subnet_public_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  map_public_ip_on_launch = true
  tags = {
    Name = "public-subnet-1"
  }
}

resource "aws_subnet" "subnet_public_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  map_public_ip_on_launch = true
  tags = {
    Name = "public-subnet-2"
  }
}

resource "aws_lb" "application_load_balancer" {
  name            = "my-application-load-balancer"
  internal        = false
  load_balancer_type = "application"
  security_groups = []  # No security groups specified for simplicity
  subnet_mapping {
    subnet_id = aws_subnet.subnet_public_1.id
  }
  subnet_mapping {
    subnet_id = aws_subnet.subnet_public_2.id
  }
  tags = {
    Environment = "production"
  }
}

resource "aws_lb_target_group" "application_target_group" {
  name     = "my-application-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id
  target_type = "instance"

  stickiness {
    type            = "lb_cookie"
    cookie_duration = 3600
  }

  tags = {
    Environment = "production"
  }
}

resource "aws_lb_listener" "application_listener" {
  load_balancer_arn = aws_lb.application_load_balancer.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.application_target_group.arn
  }
}
```

This configuration sets up an Application Load Balancer with two public subnets, a target group, and a listener that forwards HTTP traffic to the target group. The ALB is configured to use the `application` type, and the listener is set up to handle HTTP traffic on port 80.

