### Description
This Terraform script sets up a Network Load Balancer (NLB) in AWS. The NLB is configured with two subnets in different Availability Zones for high availability. The script includes the creation of the subnets and the NLB itself, ensuring that the subnets are properly mapped to the NLB.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "subnet_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "subnet-1"
  }
}

resource "aws_subnet" "subnet_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  tags = {
    Name = "subnet-2"
  }
}

resource "aws_lb" "network_load_balancer" {
  name               = "my-network-load-balancer"
  internal           = false
  load_balancer_type = "network"

  subnet_mapping {
    subnet_id = aws_subnet.subnet_1.id
  }

  subnet_mapping {
    subnet_id = aws_subnet.subnet_2.id
  }

  enable_deletion_protection = true

  tags = {
    Environment = "production"
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **VPC Creation**: A VPC is created with a CIDR block of `10.0.0.0/16`.
3. **Subnet Creation**: Two subnets are created within the VPC, each in a different Availability Zone (`us-west-2a` and `us-west-2b`).
4. **Network Load Balancer**: A Network Load Balancer is created and mapped to the two subnets. The `enable_deletion_protection` option is set to `true` to prevent accidental deletion of the NLB. Tags are added for better management and identification.

