### Description
This Terraform configuration sets up an Application Load Balancer (ALB) that forwards traffic to one or more EC2 instances in a target group. The configuration includes the following resources:
1. **aws_lb_target_group**: Defines the target group where the instances will be registered.
2. **aws_lb**: Creates the Application Load Balancer that routes traffic to the target group.
3. **aws_security_group**: Sets up a security group to control inbound and outbound traffic to the load balancer.
4. **aws_subnet**: Specifies the subnet where the load balancer will be deployed.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_security_group" "lb_sg" {
  name        = "lb_sg"
  description = "Security group for the load balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb_target_group" "lb_target_group" {
  name     = "my-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id
}

resource "aws_lb" "lb" {
  name            = "my-load-balancer"
  internal        = false
  load_balancer_type = "application"
  security_groups = [aws_security_group.lb_sg.id]

  subnet_mapping {
    subnet_id = aws_subnet.subnet.id
  }

  tags = {
    Name = "My Load Balancer"
  }
}

resource "aws_instance" "web" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID for t3.micro
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.subnet.id
  vpc_security_group_ids = [aws_security_group.lb_sg.id]

  tags = {
    Name = "Web Server"
  }
}

resource "aws_lb_target_group_attachment" "web_instance" {
  target_group_arn = aws_lb_target_group.lb_target_group.arn
  target_id        = aws_instance.web.id
  port             = 80
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **VPC and Subnet**: A VPC and a subnet are created to host the load balancer and instances.
- **Security Group**: A security group is set up to allow HTTP traffic on port 80 and unrestricted egress traffic.
- **Target Group**: An Application Load Balancer target group is defined to manage the instances.
- **Load Balancer**: An Application Load Balancer is created and attached to the subnet and security group.
- **EC2 Instance**: An EC2 instance is launched in the subnet and associated with the security group.
- **Target Group Attachment**: The EC2 instance is registered with the target group.

This configuration ensures that the load balancer forwards traffic to the EC2 instance(s) in the target group.

