### Description
This Terraform program creates an Application Load Balancer (ALB) with an HTTP listener that uses the `authenticate-cognito` action. The ALB is configured to listen on port 80 and redirect authenticated users to a target group. The Cognito user pool, user pool client, and domain are assumed to be created separately and referenced in the listener's `authenticate-cognito` action.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "front_end" {
  name               = "front-end-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = ["sg-0123456789abcdef0"]  # Replace with your security group ID
  subnets            = ["subnet-0123456789abcdef0", "subnet-0123456789abcdef1"]  # Replace with your subnet IDs

  enable_deletion_protection = true

  tags = {
    Environment = "production"
  }
}

resource "aws_lb_listener" "front_end" {
  load_balancer_arn = aws_lb.front_end.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type = "authenticate-cognito"

    authenticate_cognito {
      user_pool_arn       = "arn:aws:cognito-idp:us-west-2:123456789012:userpool/us-west-2_abcdef123"  # Replace with your Cognito user pool ARN
      user_pool_client_id = "abcdef1234567890abcdef1234567890"  # Replace with your Cognito user pool client ID
      user_pool_domain    = "your-cognito-domain"  # Replace with your Cognito domain
    }
  }

  default_action {
    type             = "forward"
    target_group_arn = "arn:aws:elasticloadbalancing:us-west-2:123456789012:targetgroup/front-end-target-group/1234567890123456"  # Replace with your target group ARN
  }
}
```

### Notes
- Replace the placeholder values for `security_groups`, `subnets`, `user_pool_arn`, `user_pool_client_id`, `user_pool_domain`, and `target_group_arn` with your actual AWS resource identifiers.
- Ensure that the Cognito user pool, user pool client, and domain are created and configured before deploying this Terraform configuration.
- The `enable_deletion_protection` attribute is set to `true` to prevent accidental deletion of the load balancer. Adjust this setting as needed.

