### Description
The Terraform program defines an Application Load Balancer (ALB) with a Lambda Target Group. It includes the necessary resources such as the ALB, listener, target group, Lambda function, and IAM roles. The Lambda function is configured to execute a Python script, and the IAM roles ensure that the Lambda function has the necessary permissions.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "example" {
  name               = "tf-example-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = ["sg-0123456789abcdef0"]
  subnets            = ["subnet-0123456789abcdef0", "subnet-0123456789abcdef1"]
}

resource "aws_lb_listener" "example" {
  load_balancer_arn = aws_lb.example.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.lambda_example.arn
  }
}

resource "aws_lb_target_group" "lambda_example" {
  name        = "tf-example-lb-tg"
  target_type = "lambda"
}

resource "aws_lambda_function" "example" {
  function_name = "tf-example-lambda"
  handler       = "index.handler"
  runtime       = "python3.8"
  role          = aws_iam_role.lambda_exec.arn

  filename         = "function.zip"
  source_code_hash = filebase64sha256("function.zip")
}

resource "aws_iam_role" "lambda_exec" {
  name = "lambda-exec-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_exec" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_exec.name
}
```

### Notes
- The `aws_lb_target_group` resource is configured for a Lambda Target Group.
- Ensure that the AWS account has the necessary permissions to create and manage Lambda functions and Load Balancers.
- The `source_code_hash` attribute in the `aws_lambda_function` resource uses the `filebase64sha256` function to compute the hash of the Lambda function's deployment package. Make sure the `function.zip` file exists in the same directory as the Terraform configuration file.

