LLM Output #0:
### Description
This Terraform configuration creates an AWS RDS MySQL instance that skips the final snapshot upon deletion. It also sets up an IAM role and a DLM lifecycle policy to manage snapshots.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_db_instance" "mysql_instance" {
  instance_class       = "db.t3.micro"
  engine               = "mysql"
  engine_version       = "8.0"
  allocated_storage    = 20
  username             = "admin"
  password             = "password123"
  db_name              = "mydatabase"
  skip_final_snapshot  = true
  backup_retention_period = 0
}

resource "aws_iam_role" "dlm_lifecycle_role" {
  name = "dlm-lifecycle-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "dlm.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "dlm_lifecycle_policy" {
  name   = "dlm-lifecycle-policy"
  role   = aws_iam_role.dlm_lifecycle_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:CreateSnapshot",
          "ec2:CreateSnapshots",
          "ec2:DeleteSnapshot",
          "ec2:DescribeInstances",
          "ec2:DescribeVolumes",
          "ec2:DescribeSnapshots",
          "ec2:CreateTags"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_dlm_lifecycle_policy" "dlm_policy" {
  description        = "MySQL instance snapshot policy"
  execution_role_arn = aws_iam_role.dlm_lifecycle_role.arn
  state              = "ENABLED"

  policy_details {
    resource_types = ["VOLUME"]

    schedule {
      name = "Daily Snapshots"

      create_rule {
        interval      = 24
        interval_unit = "HOURS"
        times         = ["03:00"]
      }

      retain_rule {
        count = 7
      }

      tags_to_add = {
        SnapshotCreator = "DLM"
      }

      copy_tags = false
    }

    target_tags = {
      Name = "mysql-instance"
    }
  }
}
```

This configuration sets up an RDS MySQL instance with the `skip_final_snapshot` option enabled, ensuring that no final snapshot is created when the instance is deleted. Additionally, it creates an IAM role and a DLM lifecycle policy to manage snapshots according to the specified schedule.

